// Generated by Heron Brush for Stride 4.4: the editor's keyframe animation, the
// buttons and trigger volumes that start it, and water volumes. Re-exporting replaces
// this file.
//
// Stride shares the level's frame -- right-handed, Y up, metres -- so the payload's
// Godot-frame channels apply directly; only map-unit channels are divided by scale.
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using Stride.Core;
using Stride.Core.Mathematics;
using Stride.Engine;
using Stride.Rendering.Compositing;
using Stride.Rendering.Images;

namespace __NAMESPACE__ {
    public sealed class HeronBrushStrideAnimation : SyncScript {
        public string DataJson { get; set; }
        // Set when a game steps the animation itself through Advance.
        [DataMemberIgnore] public bool ManualUpdate;
        public sealed class Key { public double time { get; set; } public double value { get; set; } public double incoming { get; set; } public double outgoing { get; set; } public string interpolation { get; set; } }
        public sealed class Channel { public Key[] keys { get; set; } }
        public sealed class Clip { public string name { get; set; } public string mode { get; set; } public double duration { get; set; } public Channel[] channels { get; set; } }
        public sealed class Payload { public uint version { get; set; } public double scale { get; set; } public double[] pivot { get; set; } public string selected { get; set; } public bool autoplay { get; set; } public Clip[] clips { get; set; } }
        private Payload data;
        private Clip clip;
        private double time;
        private bool playing, posed;
        private Vector3 restPosition, pivot;
        private Quaternion restRotation;
        public bool IsPlaying => playing;
        public string CurrentClip => clip?.name;
        public double ClipTime => time;
        private static bool Finite(double value) => !double.IsNaN(value) && !double.IsInfinity(value);
        private void Ensure(){
            if(data!=null)return;
            var parsed=JsonSerializer.Deserialize<Payload>(DataJson);
            if(parsed==null||parsed.version!=1||!Finite(parsed.scale)||parsed.scale<=0||parsed.pivot==null||parsed.pivot.Length!=3||
               parsed.pivot.Any(v=>!Finite(v))||parsed.clips==null||parsed.clips.Length==0||
               parsed.clips.Any(c=>c.channels==null||c.channels.Length!=6||!Finite(c.duration)||c.duration<=0))
                throw new InvalidOperationException("Invalid Heron Brush animation payload");
            clip=parsed.clips.FirstOrDefault(c=>c.name==parsed.selected)??throw new InvalidOperationException("Missing selected clip");
            data=parsed;restPosition=Entity.Transform.Position;restRotation=Entity.Transform.Rotation;
            pivot=new Vector3((float)(parsed.pivot[1]/parsed.scale),(float)(parsed.pivot[2]/parsed.scale),(float)(parsed.pivot[0]/parsed.scale));
            playing=posed=parsed.autoplay;
        }
        public override void Start(){Ensure();Apply();}
        public override void Update(){if(!ManualUpdate)Advance(Game.UpdateTime.Elapsed.TotalSeconds);}
        public bool Play(string name=null){
            Ensure();var next=data.clips.FirstOrDefault(c=>c.name==(name??data.selected));
            if(next==null)return false;clip=next;time=0;playing=posed=true;Apply();return true;
        }
        public void Activate(){
            Ensure();
            if(data.clips.Any(c=>c.name=="open")&&data.clips.Any(c=>c.name=="close")){
                var next=posed&&clip.name=="open"?"close":"open";
                var reverse=posed&&playing;var phase=Math.Min(time/clip.duration,1);
                Play(next);if(reverse)Seek((1-phase)*clip.duration);
            }
            else Play();
        }
        public void Pause(){playing=false;}
        public void Resume(){Ensure();playing=posed=true;}
        public void Stop(){Ensure();playing=posed=false;time=0;Apply();}
        public void Seek(double seconds){Ensure();if(Finite(seconds)){time=Math.Max(0,seconds);posed=true;Apply();}}
        public void Advance(double dt){
            Ensure();if(!Finite(dt)||dt<0)throw new ArgumentOutOfRangeException(nameof(dt));
            if(playing){
                time+=dt;
                if(clip.mode=="once"&&time>=clip.duration){time=clip.duration;playing=false;}
                else if(clip.mode!="once")time%=clip.duration*(clip.mode=="pingpong"?2:1);
            }
            Apply();
        }
        public static double Sample(Channel channel,double at){
            var keys=channel.keys;if(keys.Length==0)return 0;if(at<=keys[0].time)return keys[0].value;
            int lo=0,hi=keys.Length;while(lo<hi){int m=lo+(hi-lo)/2;if(keys[m].time<=at)lo=m+1;else hi=m;}
            var a=keys[lo-1];if(lo==keys.Length||a.interpolation=="hold")return a.value;
            var b=keys[lo];double duration=b.time-a.time,f=(at-a.time)/duration,u=1-f;
            if(a.interpolation=="bezier")return u*u*u*a.value+3*u*u*f*(a.value+a.outgoing*duration/3)+3*u*f*f*(b.value-b.incoming*duration/3)+f*f*f*b.value;
            return a.value+(b.value-a.value)*f;
        }
        // The Hamilton product a*b: b's rotation, then a's.
        internal static Quaternion Then(Quaternion a,Quaternion b)=>new Quaternion(
            a.W*b.X+a.X*b.W+a.Y*b.Z-a.Z*b.Y,a.W*b.Y-a.X*b.Z+a.Y*b.W+a.Z*b.X,
            a.W*b.Z+a.X*b.Y-a.Y*b.X+a.Z*b.W,a.W*b.W-a.X*b.X-a.Y*b.Y-a.Z*b.Z);
        private void Apply(){
            if(!posed){Entity.Transform.Position=restPosition;Entity.Transform.Rotation=restRotation;return;}
            double t=clip.mode=="once"?Math.Min(time,clip.duration):time%(clip.duration*(clip.mode=="pingpong"?2:1));
            if(t>clip.duration)t=2*clip.duration-t;
            var v=clip.channels.Select(channel=>Sample(channel,t)).ToArray();
            const double radians=Math.PI/180;
            // Y, then X, then Z applied first: the YXZ order every Heron Brush runtime uses.
            var q=Then(Then(Quaternion.RotationY((float)(v[5]*radians)),Quaternion.RotationX((float)(v[4]*radians))),Quaternion.RotationZ((float)(v[3]*radians)));
            Entity.Transform.Position=Vector3.Transform(restPosition-pivot,q)+pivot+new Vector3((float)(v[1]/data.scale),(float)(v[2]/data.scale),(float)(v[0]/data.scale));
            Entity.Transform.Rotation=Then(q,restRotation);
        }
    }

    public sealed class HeronBrushStrideTrigger : SyncScript {
        public string DataJson { get; set; }
        [DataMemberIgnore] public bool ManualUpdate;
        [DataMemberIgnore] public HeronBrushStrideLevel.BuiltLevel Level;
        private sealed class Payload { public string action { get; set; } public string clip { get; set; } public bool once { get; set; } public double wait { get; set; } public double[] origin { get; set; } public double[][][] volumes { get; set; } public string[] targets { get; set; } }
        private Payload data;
        private HashSet<Entity> inside=new HashSet<Entity>();
        private bool fired,pending;
        private double wait;
        // A button press: fires on the next update even when nothing walks in.
        public void Activate(){pending=true;}
        public override void Update(){if(!ManualUpdate)Advance(Game.UpdateTime.Elapsed.TotalSeconds,Level?.Activators??new List<Entity>());}
        public void Advance(double dt,IEnumerable<Entity> activators){
            if(data==null)data=JsonSerializer.Deserialize<Payload>(DataJson);
            wait=Math.Max(0,wait-dt);var now=new HashSet<Entity>();
            Entity.Transform.UpdateWorldMatrix();
            var toLocal=Matrix.Invert(Entity.Transform.WorldMatrix);var o=data.origin;
            foreach(var actor in activators){
                if(actor==null)continue;
                actor.Transform.UpdateWorldMatrix();
                var p=Vector3.TransformCoordinate(actor.Transform.WorldMatrix.TranslationVector,toLocal);
                if(data.volumes.Any(planes=>planes.Length>0&&planes.All(v=>
                    v[0]*(p.X+o[0])+v[1]*(p.Y+o[1])+v[2]*(p.Z+o[2])<=v[3]+1e-5)))now.Add(actor);
            }
            var entered=now.Any(actor=>!inside.Contains(actor));inside=now;
            var requested=pending||entered;pending=false;
            if(!requested||wait>0||(data.once&&fired))return;
            fired=true;wait=data.wait;
            foreach(var name in data.targets??Array.Empty<string>()){
                if(Level==null||!Level.Animations.TryGetValue(name,out var animation))continue;
                switch(data.action){
                    case "play":animation.Play(string.IsNullOrEmpty(data.clip)?null:data.clip);break;
                    case "open":case "close":animation.Play(data.action);break;
                    case "pause":animation.Pause();break;
                    case "resume":animation.Resume();break;
                    case "stop":animation.Stop();break;
                    case "":case "toggle":case null:animation.Activate();break;
                }
            }
        }
    }

    // One water volume: the entity's convex planes in its own frame, in metres. Its
    // collider is a trigger, so nothing here moves a body: a player asks Sample where it
    // is every step and, while that says it is in the water, takes Velocity.
    public sealed class HeronBrushStrideWater : StartupScript {
        public string DataJson { get; set; }
        public sealed class Plane { public double x { get; set; } public double y { get; set; } public double z { get; set; } public double d { get; set; } }
        public sealed class Volume { public Plane[] planes { get; set; } public double surface { get; set; } }
        public sealed class Payload {
            public uint version { get; set; } public Volume[] volumes { get; set; } public int priority { get; set; }
            public double swim_speed { get; set; } public double rise_speed { get; set; } public double sink_speed { get; set; } public double drag { get; set; }
            public double[] color { get; set; } public double opacity { get; set; } public double fog_density { get; set; }
        }
        private Payload data;
        [DataMemberIgnore] public Payload Data{get{
            if(data==null){data=JsonSerializer.Deserialize<Payload>(DataJson);if(data==null||data.version!=1)throw new InvalidOperationException(Entity?.Name+": unsupported water payload");}
            return data;
        }}
        [DataMemberIgnore] public Color3 Color=>new Color3((float)Data.color[0],(float)Data.color[1],(float)Data.color[2]);
        // How far below the surface `world` is, in metres, or -1 outside the water.
        public float Sample(Vector3 world){
            Entity.Transform.UpdateWorldMatrix();
            var matrix=Entity.Transform.WorldMatrix;
            var p=Vector3.TransformCoordinate(world,Matrix.Invert(matrix));
            var scaleY=new Vector3(matrix.M21,matrix.M22,matrix.M23).Length();
            var depth=-1.0;
            foreach(var volume in Data.volumes)
                if(volume.planes.Length>=4&&volume.planes.All(v=>v.x*p.X+v.y*p.Y+v.z*p.Z<=v.d+1e-5))
                    depth=Math.Max(depth,(volume.surface-p.Y)*scaleY);
            return (float)depth;
        }
        // Swimming: walk steers in the horizontal plane (capped at length 1), rise and
        // dive move up and down, and with neither the body sinks slowly. The current
        // velocity eases towards that at the volume's drag.
        public Vector3 Velocity(Vector3 current,Vector3 walk,bool rise,bool dive,float dt){
            var d=Data;var length=walk.Length();var k=(float)((length>1?1/length:1)*d.swim_speed);
            var wish=new Vector3(walk.X*k,(float)((rise?d.rise_speed:0)-(dive?d.rise_speed:0)-(!rise&&!dive?d.sink_speed:0)),walk.Z*k);
            return Vector3.Lerp(current,wish,(float)(1-Math.Exp(-d.drag*dt)));
        }
        // The volume `world` is in and how deep; where volumes overlap the higher
        // priority wins, then the deeper. Null when it is in none.
        public static HeronBrushStrideWater Find(IEnumerable<HeronBrushStrideWater> waters,Vector3 world,out float depth){
            HeronBrushStrideWater best=null;depth=-1;
            foreach(var water in waters){
                if(water?.Entity==null)continue;
                var d=water.Sample(world);
                if(d<0)continue;
                if(best==null||water.Data.priority>best.Data.priority||(water.Data.priority==best.Data.priority&&d>depth)){best=water;depth=d;}
            }
            return best;
        }
    }

    // Add to the camera's entity: while the camera is in water, the compositor's fog
    // post effect takes the water's colour and density, and goes back as it was when
    // the camera leaves. A game with its own underwater effect uses Find instead.
    public sealed class HeronBrushStrideWaterView : SyncScript {
        [DataMemberIgnore] public HeronBrushStrideLevel.BuiltLevel Level;
        private Fog fog;
        private bool active,enabled,skip;
        private Color3 color;
        private float density,start;
        public override void Update(){
            fog??=FindFog(SceneSystem.GraphicsCompositor?.Game);
            if(fog==null||Level==null)return;
            Entity.Transform.UpdateWorldMatrix();
            var water=HeronBrushStrideWater.Find(Level.Waters,Entity.Transform.WorldMatrix.TranslationVector,out _);
            if(water!=null){
                if(!active){enabled=fog.Enabled;color=fog.Color;density=fog.Density;start=fog.FogStart;skip=fog.SkipBackground;active=true;}
                fog.Enabled=true;fog.Color=water.Color;fog.Density=(float)water.Data.fog_density;fog.FogStart=0;
                // The sky would show through clear water.
                fog.SkipBackground=false;
            }else Restore();
        }
        public override void Cancel(){Restore();}
        private void Restore(){
            if(!active||fog==null)return;
            fog.Enabled=enabled;fog.Color=color;fog.Density=density;fog.FogStart=start;fog.SkipBackground=skip;active=false;
        }
        private static Fog FindFog(ISceneRenderer renderer){
            switch(renderer){
                case ForwardRenderer forward:return (forward.PostEffects as PostProcessingEffects)?.Fog;
                case SceneCameraRenderer camera:return FindFog(camera.Child);
                case SceneRendererCollection collection:
                    foreach(var child in collection.Children){var found=FindFog(child);if(found!=null)return found;}
                    return null;
                default:return null;
            }
        }
    }
}
